    }
    ExString=S;
    MyDBIProcess("Process", S, S2);                                             //Steven 20091004 : 紀錄按鍵被按的時間
}

void RecordChangeLogProcess(AnsiString S, AnsiString S2)                        //wei 20180625 offset Change log紀錄
